<?php
require __DIR__.'/app/bootstrap.php';$pdo=db();$cart=$_SESSION['shop_cart']??[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['product_id']??0);if($action==='remove')unset($_SESSION['shop_cart'][$id]);elseif($action==='qty'){$qty=max(0,min(10,(int)($_POST['qty']??0)));if($qty===0)unset($_SESSION['shop_cart'][$id]);else $_SESSION['shop_cart'][$id]=$qty;}redirect('cart.php');}
$rows=[];$total=0.0;if($cart){$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=$pdo->prepare("SELECT * FROM merch_catalog_products WHERE id IN ($marks) AND status='active'");$stmt->execute($ids);foreach($stmt->fetchAll() as $p){$qty=(int)($cart[$p['id']]??0);$p['qty']=$qty;$p['line_total']=$qty*(float)$p['price'];$total+=$p['line_total'];$rows[]=$p;}}
$title='Cart — Vacation Brain';require __DIR__.'/partials/header.php';
?>
<section class="dashboard"><div class="shell"><div class="dashboard-head"><div><div class="eyebrow">Shop</div><h1>Your cart</h1></div><a class="button secondary small" href="<?=e(app_url('shop.php'))?>">Continue shopping</a></div><div class="dashboard-card"><?php if(!$rows):?><h2>Your cart is empty.</h2><p class="muted">Which is financially responsible, but not very Vacation Brain.</p><?php else:?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>Qty</th><th>Price</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><strong><?=e($p['name'])?></strong></td><td><form method="post" class="inline-role"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="qty"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><input class="input compact" type="number" min="0" max="10" name="qty" value="<?=$p['qty']?>"><button class="button secondary small">Update</button></form></td><td>$<?=number_format((float)$p['price'],2)?></td><td>$<?=number_format((float)$p['line_total'],2)?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button class="text-button">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div><div class="cart-total"><span>Subtotal</span><strong>$<?=number_format($total,2)?></strong></div><div style="margin-top:16px;text-align:right"><a class="button primary" href="<?=e(app_url('checkout.php'))?>">Continue to checkout</a></div><?php endif;?></div></div></section>
